#include <cstdio>
#include <queue>

using namespace std;

const int N = 2e5 + 5;

int n, k;
int d[N];
long long ans;

void solve() {
	scanf("%d%d", &n, &k);
	ans = 0;
	priority_queue <int> q;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &d[i]);
		q.push(d[i]);
		if ((n - i + 1) % (k + 1) == 0) {
			ans += q.top();
			q.pop();
		}
	}
	printf("%lld\n", ans);
}

int main() {
	int t;
	scanf("%d", &t);
	while (t--)
		solve();
	return 0;
}

#include <cstdio>

using namespace std;

const int N = 1e4 + 5;
const int C = 1e6 + 5;

int n;
int a[N], b[N];
int cnt[C];
long long s;

bool check(int k) {
	for (int i = 1; i <= n; i++)
		cnt[a[i] % k]++;
	for (int i = 1; i <= n; i++)
		if (--cnt[b[i]] < 0) {
			cnt[b[i]] = 0;
			for (int i = 1; i <= n; i++)
				cnt[a[i] % k] = 0;
			return 0;
		}
	return 1;
}

void solve() {
	scanf("%d", &n);
	s = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		s += a[i];
	}
	for (int i = 1; i <= n; i++) {
		scanf("%d", &b[i]);
		s -= b[i];
	}
	if (s == 0) {
		printf("%d\n", check(0xc0ffee) ? 0xc0ffee : -1);
		return;
	}
	for (int i = 1; 1ll * i * i <= s; i++)
		if (s % i == 0) {
			if (check(i)) {
				printf("%d\n", i);
				return;
			}
			if (i < C && check(s / i)) {
				printf("%d\n", (int)(s / i));
				return;
			}
		}
	printf("-1\n");
}

int main() {
	int t;
	scanf("%d", &t);
	while (t--)
		solve();
	return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 3005;
const long long oo = 1e18;

int n, k;
int a[N], l[N], r[N], d[N];
long long ans;

void solve() {
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++)
		scanf("%d", &a[i]);
	ans = oo;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= k; j++)
			l[j] = r[j] = n + 1;
		for (int j = i; j; j--)
			l[a[j]] = min(l[a[j]], i - j);
		for (int j = i; j <= n; j++)
			r[a[j]] = min(r[a[j]], j - i);
		long long s = 0;
		for (int j = 1; j <= k; j++) {
			s += l[j];
			d[j] = r[j] - l[j];
		}
		sort(d + 1, d + k + 1);
		for (int j = 1; j <= (k + 1) / 2; j++)
			s += d[j];
		ans = min(ans, s);
	}
	for (int i = 1; i <= k; i++)
		ans -= abs(i - (k + 1) / 2);
	printf("%lld\n", ans);
}

int main() {
	int T;
	scanf("%d", &T);
	while (T--)
		solve();
	return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 4e5 + 5;
const long long oo = 1e18;

int n, k;
int a[N];
int last[N], dd[N];
long long s, d, ans;

void solve() {
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++)
		last[i] = dd[i] = 0;
	s = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		if (!last[a[i]])
			s += i - 1;
		else {
			int pre = last[a[i]];
			int mid = (pre + i) / 2;
			if ((pre + i) & 1) {
				dd[mid]--;
				dd[mid + 1]--;
			} else
				dd[mid] -= 2;
		}
		dd[i] += 2;
		last[a[i]] = i;
	}
	ans = oo;
	d = -k;
	for (int i = 1; i <= n; i++) {
		ans = min(ans, s);
		d += dd[i];
		s += d;
	}
	for (int i = 1; i <= k; i++)
		ans -= abs(i - (k + 1) / 2);
	printf("%lld\n", ans);
}

int main() {
	int T;
	scanf("%d", &T);
	while (T--)
		solve();
	return 0;
}
